import React, { useState } from "react";
import { FiMenu, FiX } from "react-icons/fi";
import { useTranslation } from "gatsby-plugin-react-i18next";
import menuData from "../data/data.json";

export default function Navigation() {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const menuItems = menuData.menu;

  return (
    <nav className="bg-neutral shadow-md p-4 relative">
      <div className="container mx-auto flex justify-between items-center">
        
        {/* Desktop Menu */}
        <ul className="hidden md:flex space-x-6">
          {menuItems.map((item, index) => (
            <li key={index}>
              <a href={item === "home" ? `/` : `/${item}`} className="text-primary hover:text-secondary">{t(`menu.${item}`)}</a>
            </li>
          ))}
        </ul>

        {/* Mobile Menu Button */}
        <button onClick={() => setIsOpen(!isOpen)} className="md:hidden">
          {isOpen ? <FiMenu size={24} /> : <FiX size={24} />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <ul className="bg-neutral md:hidden shadow-md p-4 space-y-2">
          {menuItems.map((item, index) => (
            <li key={index}>
              <a href={`#${item}`} className="text-accent hover:text-secondary block">{t(item)}</a>
            </li>
          ))}
        </ul>
      )}
    </nav>
  );
}
